}

# Mock fallback path execution for testing
execute_fallback_path() {
    local path_id="${1}"
    log_info "Mock fallback path execution: $path_id"
    
    # Simulate work
    sleep 1
    
    # Simulate success for primary_service_call, failure for others to test fallback behavior
    case "$path_id" in
        "primary_service_call")
            log_success "Primary service call succeeded"
            return 0
            ;;
        "secondary_service_call") 
            log_warning "Secondary service call failed"
            return 1
            ;;
        "cache_fallback_call")
            log_warning "Cache fallback failed"
            return 1
            ;;
        "default_response_call")
            log_success "Default response call succeeded"
            return 0
            ;;
        *)
            log_info "Unknown fallback path succeeded: $path_id"
            return 0
            ;;
    esac
}

# Workflow Execution

# Node: initialize_memory_system
/bin/bash -c "set -euo pipefail
echo \"🧠 Initializing AI Chat Memory System...\"

# Configuration validation
CONV_ID=\"\${CONVERSATION_ID:-default_chat}\"
MAX_TURNS=\"\${MAX_MEMORY_TURNS:-10}\"
SYSTEM_PROMPT=\"\${CHAT_SYSTEM_PROMPT:-You are a helpful AI assistant. You remember previous conversations and provide contextual responses.}\"
USER_MSG=\"\${USER_INPUT:-Hello! How are you today?}\"

echo \"🔧 Memory Configuration:\"
echo \"  Conversation ID: \\\$CONV_ID\"
echo \"  Max Memory Turns: \\\$MAX_TURNS\"
echo \"  System Prompt Length: \${#SYSTEM_PROMPT} characters\"
echo \"  User Input: \${USER_MSG:0:50}\${USER_MSG:50:+...}\"

# Create memory storage directories
mkdir -p /tmp/ai_memory
mkdir -p /tmp/ai_memory/conversations
mkdir -p /tmp/ai_memory/context

# Initialize conversation history file
HISTORY_FILE=\"/tmp/ai_memory/conversations/\$(get_var "CONV_ID" "initialize_memory_system").json\"
CONTEXT_FILE=\"/tmp/ai_memory/context/\$(get_var "CONV_ID" "initialize_memory_system")_context.txt\"

# Create history file if it doesn't exist
if [ ! -f \"\\\$HISTORY_FILE\" ]; then
  echo '{\"conversation_id\":\"'\\\$CONV_ID'\",\"created_at\":\"'\$(date -Iseconds)'\",\"turns\":[]}' > \"\\\$HISTORY_FILE\"
  echo \"📝 Created new conversation history\"
else
  echo \"📖 Loading existing conversation history\"
fi

# Initialize context awareness
echo \"Conversation Context for: \\\$CONV_ID\" > \"\\\$CONTEXT_FILE\"
echo \"System Prompt: \\\$SYSTEM_PROMPT\" >> \"\\\$CONTEXT_FILE\"
echo \"Created: \$(date)\" >> \"\\\$CONTEXT_FILE\"
echo \"Max Turns: \\\$MAX_TURNS\" >> \"\\\$CONTEXT_FILE\"
echo \"---\" >> \"\\\$CONTEXT_FILE\"

echo \"✅ Memory system initialized successfully\"
"

# Node: load_conversation_history
/bin/bash -c "set -euo pipefail
echo \"📚 Loading conversation history...\"

CONV_ID=\"\${CONVERSATION_ID:-default_chat}\"
MAX_TURNS=\"\${MAX_MEMORY_TURNS:-10}\"
HISTORY_FILE=\"/tmp/ai_memory/conversations/\$(get_var "CONV_ID" "load_conversation_history").json\"

echo \"📁 History file: \\\$HISTORY_FILE\"

# Extract conversation turns (last N turns)
if [ -f \"\\\$HISTORY_FILE\" ]; then
  # Count total turns
  TOTAL_TURNS=\$(jq '.turns | length' \"\\\$HISTORY_FILE\" 2>/dev/null || echo \"0\")
  echo \"📊 Total conversation turns: \\\$TOTAL_TURNS\"
  
  if [ \"\\\$TOTAL_TURNS\" -gt 0 ]; then
    # Get last MAX_TURNS turns
    START_INDEX=\$((TOTAL_TURNS > MAX_TURNS ? TOTAL_TURNS - MAX_TURNS : 0))
    
    echo \"🔍 Loading last \\\$MAX_TURNS turns (starting from index \\\$START_INDEX)\"
    
    # Extract recent history for context
    jq -r --argjson start \"\\\$START_INDEX\" '.turns[\\\$start:] | .[] | \"Turn \" + (.turn_number|@sh) + \" (\" + .timestamp + \"):\\\\nUser: \" + .user_message + \"\\\\nAI: \" + .ai_response + \"\\\\n\"' \"\\\$HISTORY_FILE\" > /tmp/recent_history.txt 2>/dev/null || echo \"\" > /tmp/recent_history.txt
    
    # Create formatted context for LLM
    echo \"Previous Conversation Context:\" > /tmp/formatted_context.txt
    cat /tmp/recent_history.txt >> /tmp/formatted_context.txt
    echo \"---\" >> /tmp/formatted_context.txt
    
    echo \"📖 Loaded conversation context:\"
    head -c 300 /tmp/formatted_context.txt
    echo \"...\"
    
  else
    echo \"💬 No previous conversation history found - starting fresh\"
    echo \"No previous conversation context.\" > /tmp/formatted_context.txt
  fi
  
else
  echo \"❌ History file not found - this shouldn't happen after initialization\"
  echo \"No conversation context available.\" > /tmp/formatted_context.txt
fi

echo \"✅ History loading complete\"
"

# Node: prepare_llm_context

# Node: prepare_llm_context (Prepare LLM Context)
execute_template_transform_prepare_llm_context() {
    log_step "🔧 Template Transform: Prepare LLM Context"

    local output_var="prepared_context"
    local template_content=""

    # Inline template content
    template_content=''
    log_debug "Using inline template content"

    # Validate template was resolved
    if [[ -z "$template_content" ]]; then
        log_error "Failed to resolve template content"
        set_workflow_var "$output_var" ""
        return 1
    fi

    log_debug "Template resolved, length: ${#template_content} characters"

    # Apply template parameters (basic substitution)
    local rendered_content="$template_content"

    # No template parameters configured
    log_debug "No template parameters to process"

    # Advanced template functions processing
    rendered_content=$(process_template_functions "$rendered_content")
    
    # Additional variable substitution for workflow variables
    rendered_content=$(substitute_variables "$rendered_content")

    # Set output variable
    set_workflow_var "$output_var" "$rendered_content"

    log_success "Template transformed and stored in $output_var"
    log_debug "Template output length: ${#rendered_content} characters"
}

# Advanced template function processor for node prepare_llm_context
process_template_functions_prepare_llm_context() {
    local content="$1"

    # {{#date}} -> current date (YYYY-MM-DD)
    content="${content//\{\{#date\}\}/$(date '+%Y-%m-%d')}"

    # {{#time}} -> current time (HH:MM:SS)
    content="${content//\{\{#time\}\}/$(date '+%H:%M:%S')}"

    # {{#datetime}} -> current date and time (ISO 8601)
    content="${content//\{\{#datetime\}\}/$(date -Iseconds)}"

    # {{#timestamp}} -> current Unix timestamp
    content="${content//\{\{#timestamp\}\}/$(date '+%s')}"

    # {{#uuid}} -> generate UUID (fallback if uuidgen not available)
    if command -v uuidgen >/dev/null 2>&1; then
        content="${content//\{\{#uuid\}\}/$(uuidgen)}"
    else
        # Fallback UUID generation using date and random
        local fallback_uuid="uuid-$(date +%s)-$RANDOM"
        content="${content//\{\{#uuid\}\}/$fallback_uuid}"
    fi

    # {{#random}} -> random number (0-32767)
    content="${content//\{\{#random\}\}/$RANDOM}"

    # {{#hostname}} -> current hostname
    content="${content//\{\{#hostname\}\}/$(hostname 2>/dev/null || echo 'unknown')}"

    # {{#user}} -> current user
    content="${content//\{\{#user\}\}/$(whoami 2>/dev/null || echo 'unknown')}"

    # {{#pwd}} -> current working directory
    content="${content//\{\{#pwd\}\}/$(pwd)}"

    # Process variable-based functions with regex matching
    # {{#base64:variable}} -> base64 encode variable
    while [[ "$content" =~ \{\{#base64:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            if command -v base64 >/dev/null 2>&1; then
                encoded_value="$(echo -n "$var_value" | base64 -w 0)"
            else
                log_warning "base64 command not available, skipping encoding for $var_name"
                encoded_value="$var_value"
            fi
        fi
        
        content="${content//\{\{#base64:$var_name\}\}/$encoded_value}"
    done

    # {{#url_encode:variable}} -> URL encode variable
    while [[ "$content" =~ \{\{#url_encode:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            # Simple URL encoding (encode spaces and special characters)
            encoded_value="$(echo "$var_value" | sed 's/ /%20/g; s/&/%26/g; s/?/%3F/g; s/=/%3D/g')"
        fi
        
        content="${content//\{\{#url_encode:$var_name\}\}/$encoded_value}"
    done

    # {{#upper:variable}} -> uppercase variable
    while [[ "$content" =~ \{\{#upper:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local upper_value=""
        
        if [[ -n "$var_value" ]]; then
            upper_value="$(echo "$var_value" | tr '[:lower:]' '[:upper:]')"
        fi
        
        content="${content//\{\{#upper:$var_name\}\}/$upper_value}"
    done

    # {{#lower:variable}} -> lowercase variable
    while [[ "$content" =~ \{\{#lower:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local lower_value=""
        
        if [[ -n "$var_value" ]]; then
            lower_value="$(echo "$var_value" | tr '[:upper:]' '[:lower:]')"
        fi
        
        content="${content//\{\{#lower:$var_name\}\}/$lower_value}"
    done

    # {{#length:variable}} -> length of variable
    while [[ "$content" =~ \{\{#length:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local length_value="${#var_value}"
        
        content="${content//\{\{#length:$var_name\}\}/$length_value}"
    done

    # {{#json_escape:variable}} -> JSON escape variable
    while [[ "$content" =~ \{\{#json_escape:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local escaped_value=""
        
        if [[ -n "$var_value" ]]; then
            # Basic JSON escaping
            escaped_value="$(echo "$var_value" | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\n/\\n/g; s/\r/\\r/g')"
        fi
        
        content="${content//\{\{#json_escape:$var_name\}\}/$escaped_value}"
    done

    echo "$content"
}

# Use the node-specific template function processor
process_template_functions() {
    process_template_functions_prepare_llm_context "$1"
}
execute_template_transform_prepare_llm_context

# Node: call_ai_llm
# Function to validate and extract content from API response
extract_llm_content() {
    local response="$1"
    if [[ -n "$response" ]] && echo "$response" | jq -e '.choices[0].message.content' >/dev/null 2>&1; then
        echo "$response" | jq -r '.choices[0].message.content'
        return 0
    else
        return 1
    fi
}

# Three-stage LLM fallback: OpenAI -> LLMv7 -> Demo
llm_response=""
llm_content=""

# Stage 1: Try OpenAI if API key is available
if [[ -n "${OPENAI_API_KEY:-}" ]]; then
    log_info "Using OpenAI API..."
    llm_response=$(curl -s -X POST "https://api.openai.com/v1/chat/completions" \
      -H "Authorization: Bearer $OPENAI_API_KEY" \
      -H "Content-Type: application/json" \
      -d '{"model": "gpt-3.5-turbo", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "OpenAI API successful"
    else
        log_warning "OpenAI API failed, trying LLMv7..."
    fi
fi

# Stage 2: Try LLMv7 if OpenAI failed or no key available
if [[ -z "$llm_content" ]]; then
    if [[ -z "${OPENAI_API_KEY:-}" ]]; then
        log_info "OPENAI_API_KEY not set, using LLMv7..."
    fi
    
    llm_response=$(curl -s -X POST "https://api.llm7.io/v1/chat/completions" \
      -H "Content-Type: application/json" \
      -d '{"model": "default", "messages": [{"role": "user", "content": "Hello"}]}' \
      --connect-timeout 30 --max-time 60)
    if extract_llm_content "$llm_response" >/dev/null 2>&1; then
        llm_content=$(extract_llm_content "$llm_response")
        log_info "LLMv7 API successful"
    else
        log_warning "LLMv7 API also failed, using mock response"
    fi
fi

# Stage 3: Final fallback to demo response
if [[ -z "$llm_content" ]]; then
    llm_content="Mock LLM Response: This is a simulated response because all API calls failed. Original prompt was: Hello"
    log_warning "Using mock response as final fallback"
fi

# Store the content in workflow variable for other nodes to reference
set_workflow_var "llm_content" "$llm_content"
set_workflow_var "llm_success" "true"

# Output the final content
echo "$llm_content"

# Node: save_conversation_turn
/bin/bash -c "set -euo pipefail
echo \"💾 Saving conversation turn...\"

CONV_ID=\"\${CONVERSATION_ID:-default_chat}\"
USER_MSG=\"\$(get_var "USER_INPUT" "save_conversation_turn")\"
AI_RESPONSE=\"\$(get_var "LLM_CONTENT" "save_conversation_turn")\"
HISTORY_FILE=\"/tmp/ai_memory/conversations/\$(get_var "CONV_ID" "save_conversation_turn").json\"
TIMESTAMP=\$(date -Iseconds)

echo \"📝 Turn details:\"
echo \"  User: \${USER_MSG:0:100}\${USER_MSG:100:+...}\"
echo \"  AI: \${AI_RESPONSE:0:100}\${AI_RESPONSE:100:+...}\"
echo \"  Timestamp: \\\$TIMESTAMP\"

# Get current turn number
CURRENT_TURNS=\$(jq '.turns | length' \"\\\$HISTORY_FILE\" 2>/dev/null || echo \"0\")
TURN_NUMBER=\$((CURRENT_TURNS + 1))

# Create new turn object
NEW_TURN=\$(jq -n \\
  --arg turn \"\\\$TURN_NUMBER\" \\
  --arg timestamp \"\\\$TIMESTAMP\" \\
  --arg user \"\\\$USER_MSG\" \\
  --arg ai \"\\\$AI_RESPONSE\" \\
  '{
    turn_number: (\\\$turn | tonumber),
    timestamp: \\\$timestamp,
    user_message: \\\$user,
    ai_response: \\\$ai
  }')

# Add turn to history file
jq --argjson new_turn \"\\\$NEW_TURN\" '.turns += [\\\$new_turn]' \"\\\$HISTORY_FILE\" > \"\$(get_var "HISTORY_FILE" "save_conversation_turn").tmp\"
mv \"\$(get_var "HISTORY_FILE" "save_conversation_turn").tmp\" \"\\\$HISTORY_FILE\"

echo \"✅ Turn \\\$TURN_NUMBER saved successfully\"
"

# Node: update_context_summary
/bin/bash -c "set -euo pipefail
echo \"🔄 Updating conversation context summary...\"

CONV_ID=\"\${CONVERSATION_ID:-default_chat}\"
CONTEXT_FILE=\"/tmp/ai_memory/context/\$(get_var "CONV_ID" "update_context_summary")_context.txt\"
USER_MSG=\"\$(get_var "USER_INPUT" "update_context_summary")\"
AI_RESPONSE=\"\$(get_var "LLM_CONTENT" "update_context_summary")\"

echo \"📋 Context file: \\\$CONTEXT_FILE\"

# Add current exchange to context summary
echo \"\" >> \"\\\$CONTEXT_FILE\"
echo \"Turn \$(date '+%Y-%m-%d %H:%M'):\" >> \"\\\$CONTEXT_FILE\"
echo \"User: \${USER_MSG:0:200}\${USER_MSG:200:+...}\" >> \"\\\$CONTEXT_FILE\"
echo \"AI: \${AI_RESPONSE:0:200}\${AI_RESPONSE:200:+...}\" >> \"\\\$CONTEXT_FILE\"

# Keep context file manageable (last 50 lines)
tail -n 50 \"\\\$CONTEXT_FILE\" > \"\$(get_var "CONTEXT_FILE" "update_context_summary").tmp\"
mv \"\$(get_var "CONTEXT_FILE" "update_context_summary").tmp\" \"\\\$CONTEXT_FILE\"

echo \"📊 Context summary updated\"

# Display recent context
echo \"🔍 Recent conversation context:\"
tail -n 10 \"\\\$CONTEXT_FILE\"

echo \"✅ Context update complete\"
"

# Node: generate_memory_report

# Node: generate_memory_report (Generate Memory Report)
execute_template_transform_generate_memory_report() {
    log_step "🔧 Template Transform: Generate Memory Report"

    local output_var="memory_report"
    local template_content=""

    # Inline template content
    template_content=''
    log_debug "Using inline template content"

    # Validate template was resolved
    if [[ -z "$template_content" ]]; then
        log_error "Failed to resolve template content"
        set_workflow_var "$output_var" ""
        return 1
    fi

    log_debug "Template resolved, length: ${#template_content} characters"

    # Apply template parameters (basic substitution)
    local rendered_content="$template_content"

    # No template parameters configured
    log_debug "No template parameters to process"

    # Advanced template functions processing
    rendered_content=$(process_template_functions "$rendered_content")
    
    # Additional variable substitution for workflow variables
    rendered_content=$(substitute_variables "$rendered_content")

    # Set output variable
    set_workflow_var "$output_var" "$rendered_content"

    log_success "Template transformed and stored in $output_var"
    log_debug "Template output length: ${#rendered_content} characters"
}

# Advanced template function processor for node generate_memory_report
process_template_functions_generate_memory_report() {
    local content="$1"

    # {{#date}} -> current date (YYYY-MM-DD)
    content="${content//\{\{#date\}\}/$(date '+%Y-%m-%d')}"

    # {{#time}} -> current time (HH:MM:SS)
    content="${content//\{\{#time\}\}/$(date '+%H:%M:%S')}"

    # {{#datetime}} -> current date and time (ISO 8601)
    content="${content//\{\{#datetime\}\}/$(date -Iseconds)}"

    # {{#timestamp}} -> current Unix timestamp
    content="${content//\{\{#timestamp\}\}/$(date '+%s')}"

    # {{#uuid}} -> generate UUID (fallback if uuidgen not available)
    if command -v uuidgen >/dev/null 2>&1; then
        content="${content//\{\{#uuid\}\}/$(uuidgen)}"
    else
        # Fallback UUID generation using date and random
        local fallback_uuid="uuid-$(date +%s)-$RANDOM"
        content="${content//\{\{#uuid\}\}/$fallback_uuid}"
    fi

    # {{#random}} -> random number (0-32767)
    content="${content//\{\{#random\}\}/$RANDOM}"

    # {{#hostname}} -> current hostname
    content="${content//\{\{#hostname\}\}/$(hostname 2>/dev/null || echo 'unknown')}"

    # {{#user}} -> current user
    content="${content//\{\{#user\}\}/$(whoami 2>/dev/null || echo 'unknown')}"

    # {{#pwd}} -> current working directory
    content="${content//\{\{#pwd\}\}/$(pwd)}"

    # Process variable-based functions with regex matching
    # {{#base64:variable}} -> base64 encode variable
    while [[ "$content" =~ \{\{#base64:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            if command -v base64 >/dev/null 2>&1; then
                encoded_value="$(echo -n "$var_value" | base64 -w 0)"
            else
                log_warning "base64 command not available, skipping encoding for $var_name"
                encoded_value="$var_value"
            fi
        fi
        
        content="${content//\{\{#base64:$var_name\}\}/$encoded_value}"
    done

    # {{#url_encode:variable}} -> URL encode variable
    while [[ "$content" =~ \{\{#url_encode:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local encoded_value=""
        
        if [[ -n "$var_value" ]]; then
            # Simple URL encoding (encode spaces and special characters)
            encoded_value="$(echo "$var_value" | sed 's/ /%20/g; s/&/%26/g; s/?/%3F/g; s/=/%3D/g')"
        fi
        
        content="${content//\{\{#url_encode:$var_name\}\}/$encoded_value}"
    done

    # {{#upper:variable}} -> uppercase variable
    while [[ "$content" =~ \{\{#upper:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local upper_value=""
        
        if [[ -n "$var_value" ]]; then
            upper_value="$(echo "$var_value" | tr '[:lower:]' '[:upper:]')"
        fi
        
        content="${content//\{\{#upper:$var_name\}\}/$upper_value}"
    done

    # {{#lower:variable}} -> lowercase variable
    while [[ "$content" =~ \{\{#lower:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local lower_value=""
        
        if [[ -n "$var_value" ]]; then
            lower_value="$(echo "$var_value" | tr '[:upper:]' '[:lower:]')"
        fi
        
        content="${content//\{\{#lower:$var_name\}\}/$lower_value}"
    done

    # {{#length:variable}} -> length of variable
    while [[ "$content" =~ \{\{#length:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local length_value="${#var_value}"
        
        content="${content//\{\{#length:$var_name\}\}/$length_value}"
    done

    # {{#json_escape:variable}} -> JSON escape variable
    while [[ "$content" =~ \{\{#json_escape:([^}]+)\}\} ]]; do
        local var_name="${BASH_REMATCH[1]}"
        local var_value="$(get_workflow_var "$var_name" "")"
        local escaped_value=""
        
        if [[ -n "$var_value" ]]; then
            # Basic JSON escaping
            escaped_value="$(echo "$var_value" | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\n/\\n/g; s/\r/\\r/g')"
        fi
        
        content="${content//\{\{#json_escape:$var_name\}\}/$escaped_value}"
    done

    echo "$content"
}

# Use the node-specific template function processor
process_template_functions() {
    process_template_functions_generate_memory_report "$1"
}
execute_template_transform_generate_memory_report

